  if (v == null) return null;
  final nDuration = niceDuration(v);
  if (nDuration != null) return nDuration;
  if (v is String) {
    return switch (v) {
      'Durations.short1' => Durations.short1,
      'Durations.short2' => Durations.short2,
      'Durations.short3' => Durations.short3,
      'Durations.short4' => Durations.short4,
      'Durations.medium1' => Durations.medium1,
      'Durations.medium2' => Durations.medium2,
      'Durations.medium3' => Durations.medium3,
      'Durations.medium4' => Durations.medium4,
      'Durations.long1' => Durations.long1,
      'Durations.long2' => Durations.long2,
      'Durations.long3' => Durations.long3,
      'Durations.long4' => Durations.long4,
      'Durations.extralong1' => Durations.extralong1,
      'Durations.extralong2' => Durations.extralong2,
      'Durations.extralong3' => Durations.extralong3,
      'Durations.extralong4' => Durations.extralong4,
      'zero' => Duration.zero,
      _ => fuseBad('Duration', v),
    };
  }
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return Duration(days: decInt(m['days']) ?? 0, hours: decInt(m['hours']) ?? 0, minutes: decInt(m['minutes']) ?? 0, seconds: decInt(m['seconds']) ?? 0, milliseconds: decInt(m['milliseconds']) ?? 0, microseconds: decInt(m['microseconds']) ?? 0);
  }
  return fuseBad('Duration', v);
}

StackTrace? decStackTrace(Object? v) {
  if (v == null) return null;
  if (v is String) {
    return switch (v) {
      'empty' => StackTrace.empty,
      _ => fuseBad('StackTrace', v),
    };
  }
  final m = v as Map;
  switch (m[r'$']) {
    case 'fromString':
      return StackTrace.fromString(fuseReq(decString(m['stackTraceString']), 'StackTrace.fromString', 'stackTraceString'));
  }
  return fuseBad('StackTrace', v);
}

// ── encoders (Dart -> JSON): results, mirrored state, events ────────────────

Map<String, Object?>? encAudioCache(audioplayers.AudioCache? v) => v == null
    ? null
    : {
        'prefix': v.prefix,
        'cacheId': v.cacheId,
      };

Map<String, Object?>? encAudioContext(audioplayers.AudioContext? v) => v == null
    ? null
    : {
        'android': encAudioContextAndroid(v.android),
        'iOS': encAudioContextIOS(v.iOS),
      };

Map<String, Object?>? encAudioContextAndroid(audioplayers.AudioContextAndroid? v) => v == null
    ? null
    : {
        'isSpeakerphoneOn': v.isSpeakerphoneOn,
        'audioMode': v.audioMode.name,
        'stayAwake': v.stayAwake,
        'contentType': v.contentType.name,
        'usageType': v.usageType.name,
        'audioFocus': v.audioFocus.name,
      };

Map<String, Object?>? encAudioContextIOS(audioplayers.AudioContextIOS? v) => v == null
    ? null
    : {
        'category': v.category.name,
        'options': v.options.map((e) => e.name).toList(),
      };

Map<String, Object?>? encAudioEvent(audioplayers.AudioEvent? v) => v == null
    ? null
    : {
        'eventType': v.eventType.name,
        'duration': niceEncDuration(v.duration),
        'logMessage': v.logMessage,
        'isPrepared': v.isPrepared,
      };

Map<String, Object?>? encAudioPlayer(audioplayers.AudioPlayer? v) => v == null
    ? null
    : {
        'playerId': v.playerId,
      };

Map<String, Object?>? encGlobalAudioEvent(audioplayers.GlobalAudioEvent? v) => v == null
    ? null
    : {
        'eventType': v.eventType.name,
        'logMessage': v.logMessage,
      };

